from __future__ import annotations

import os
import uuid
from collections.abc import Callable
from urllib.parse import urlsplit

from .args import get_path as _get_path
from .checks import assert_dir, exists
from .types import PathIn


def get_path(path: PathIn | None, *paths: PathIn) -> str | None:
    """Alias of :func:`fsutil.args.get_path`."""
    return _get_path(path, *paths)


def get_filename(path: PathIn) -> str:
    """Return the filename portion of a local path or URL."""
    normalized = _get_path(path)
    filepath = urlsplit(normalized).path
    return os.path.basename(filepath)


def get_file_basename(path: PathIn) -> str:
    """Return the filename without extension."""
    basename, _ = split_filename(path)
    return basename


def get_file_extension(path: PathIn) -> str:
    """Return the filename extension without the leading dot."""
    _, extension = split_filename(path)
    return extension


def get_parent_dir(path: PathIn, levels: int = 1) -> str:
    """Return the parent directory moving upward by ``levels`` components."""
    normalized = _get_path(path)
    steps = max(1, int(levels))
    return join_path(normalized, *(os.pardir for _ in range(steps)))


def get_unique_name(
    path: PathIn,
    prefix: str = "",
    suffix: str = "",
    extension: str = "",
    separator: str = "-",
) -> str:
    """Return a unique filename or directory name for an existing directory."""
    normalized = _get_path(path)
    assert_dir(normalized)
    ext = extension.lstrip(".").strip()
    while True:
        parts = [part for part in (prefix.strip(), str(uuid.uuid4()), suffix.strip()) if part]
        name = separator.join(parts) if parts else str(uuid.uuid4())
        if ext:
            name = f"{name}.{ext}"
        if not exists(join_path(normalized, name)):
            return name


def join_filename(basename: str, extension: str) -> str:
    """Build a filename from basename and extension."""
    base = basename.rstrip(".").strip()
    ext = extension.strip().lstrip(".")
    if base and ext:
        return f"{base}.{ext}"
    return base or ext


def join_filepath(dirpath: PathIn, filename: str) -> str:
    """Join a directory path and filename into a file path."""
    return join_path(dirpath, filename)


def join_path(path: PathIn, *paths: PathIn) -> str:
    """Join path parts and normalize the result."""
    basepath = _get_path(path)
    if os.path.isfile(basepath) and get_file_extension(basepath) in {"py", "pyc", "pyo"}:
        basepath = os.path.dirname(os.path.realpath(basepath))
    segments = [basepath]
    for item in paths:
        part = _get_path(item)
        segments.append(part.lstrip("/\\"))
    return os.path.normpath(os.path.join(*segments))


def split_filename(path: PathIn) -> tuple[str, str]:
    """Split a path into filename basename and extension."""
    filename = get_filename(path)
    basename, extension = os.path.splitext(filename)
    return basename, extension.lstrip(".")


def split_filepath(path: PathIn) -> tuple[str, str]:
    """Split a path into directory path and filename."""
    normalized = _get_path(path)
    return os.path.dirname(normalized), get_filename(normalized)


def split_path(path: PathIn) -> list[str]:
    """Split a path into its normalized components."""
    normalized = _get_path(path)
    head, tail = os.path.split(normalized)
    return [item for item in head.split(os.sep) + ([tail] if tail else []) if item]


def transform_filepath(
    path: PathIn,
    dirpath: str | Callable[[str], str] | None = None,
    basename: str | Callable[[str], str] | None = None,
    extension: str | Callable[[str], str] | None = None,
    filename: str | Callable[[str], str] | None = None,
) -> str:
    """Return a file path with selected parts replaced."""

    def _resolve(
        new_value: str | Callable[[str], str] | None,
        old_value: str,
    ) -> str:
        if new_value is None:
            return old_value
        return new_value(old_value) if callable(new_value) else new_value

    if all(value is None for value in (dirpath, basename, extension, filename)):
        raise ValueError("at least one replacement argument is required")
    old_dirpath, old_filename = split_filepath(path)
    new_dirpath = _resolve(dirpath, old_dirpath)
    if filename is not None:
        new_filename = _resolve(filename, old_filename)
    else:
        old_basename, old_extension = split_filename(old_filename)
        new_basename = _resolve(basename, old_basename)
        new_extension = _resolve(extension, old_extension)
        new_filename = join_filename(new_basename, new_extension)
    return join_filepath(new_dirpath, new_filename)

