from __future__ import annotations

import os

from .args import get_path as _get_path
from .types import PathIn


def exists(path: PathIn | None) -> bool:
    """Return ``True`` when the path exists."""
    normalized = _get_path(path)
    return bool(normalized) and os.path.exists(normalized)


def is_file(path: PathIn | None) -> bool:
    """Return ``True`` when the path exists and is a file."""
    normalized = _get_path(path)
    return bool(normalized) and os.path.isfile(normalized)


def is_dir(path: PathIn | None) -> bool:
    """Return ``True`` when the path exists and is a directory."""
    normalized = _get_path(path)
    return bool(normalized) and os.path.isdir(normalized)


def assert_exists(path: PathIn) -> None:
    """Raise if the path does not exist."""
    normalized = _get_path(path)
    if not exists(normalized):
        raise FileNotFoundError(f"path does not exist: {normalized}")


def assert_not_exists(path: PathIn) -> None:
    """Raise if the path already exists."""
    normalized = _get_path(path)
    if exists(normalized):
        raise FileExistsError(f"path already exists: {normalized}")


def assert_file(path: PathIn) -> None:
    """Raise if the path is not an existing file."""
    normalized = _get_path(path)
    if not exists(normalized):
        raise FileNotFoundError(f"file does not exist: {normalized}")
    if not is_file(normalized):
        raise IsADirectoryError(f"path is not a file: {normalized}")


def assert_dir(path: PathIn) -> None:
    """Raise if the path is not an existing directory."""
    normalized = _get_path(path)
    if not exists(normalized):
        raise FileNotFoundError(f"directory does not exist: {normalized}")
    if not is_dir(normalized):
        raise NotADirectoryError(f"path is not a directory: {normalized}")


def assert_not_file(path: PathIn) -> None:
    """Raise if a file exists at the given path."""
    normalized = _get_path(path)
    if is_file(normalized):
        raise FileExistsError(f"file already exists: {normalized}")


def assert_not_dir(path: PathIn) -> None:
    """Raise if a directory exists at the given path."""
    normalized = _get_path(path)
    if is_dir(normalized):
        raise FileExistsError(f"directory already exists: {normalized}")


def is_empty(path: PathIn) -> bool:
    """Return whether the existing path is an empty file or directory."""
    normalized = _get_path(path)
    assert_exists(normalized)
    if is_dir(normalized):
        return is_empty_dir(normalized)
    return is_empty_file(normalized)


def is_empty_file(path: PathIn) -> bool:
    """Return whether the file is empty."""
    from .info import get_file_size

    return get_file_size(path) == 0


def is_empty_dir(path: PathIn) -> bool:
    """Return whether the directory has no entries."""
    normalized = _get_path(path)
    assert_dir(normalized)
    return len(os.listdir(normalized)) == 0

