from __future__ import annotations

import os
import stat

from .args import get_path as _get_path
from .checks import assert_exists
from .types import PathIn


def get_permissions(path: PathIn) -> int:
    """Return permission bits such as ``0o755`` for a file or directory."""
    normalized = _get_path(path)
    assert_exists(normalized)
    return stat.S_IMODE(os.stat(normalized).st_mode)


def set_permissions(path: PathIn, value: int | str) -> int:
    """Set permission bits from either octal-style digits or an octal int."""
    normalized = _get_path(path)
    assert_exists(normalized)
    mode = _normalize_permission_value(value)
    os.chmod(normalized, mode)
    return mode


def _normalize_permission_value(value: int | str) -> int:
    if isinstance(value, str):
        text = value.strip().lower()
        if text.startswith("0o"):
            text = text[2:]
        if not text or any(char not in "01234567" for char in text):
            raise ValueError(f"invalid permission value: {value!r}")
        return int(text, 8)
    if value < 0:
        raise ValueError("permission value must be non-negative")
    if value <= 0o777:
        return value
    text = str(value)
    if any(char not in "01234567" for char in text):
        raise ValueError(f"invalid permission value: {value!r}")
    return int(text, 8)

