from __future__ import annotations

import os
import shutil
from typing import Any

from .args import get_path as _get_path
from .checks import (
    assert_dir,
    assert_file,
    assert_not_dir,
    assert_not_exists,
    assert_not_file,
    exists,
    is_dir,
    is_empty_dir,
    is_empty_file,
    is_file,
)
from .io import (
    create_file,
    download_file,
    list_dirs,
    list_files,
    search_dirs,
    search_files,
)
from .paths import (
    get_file_basename,
    get_file_extension,
    get_filename,
    join_filename,
    join_filepath,
    join_path,
    split_filepath,
)
from .types import PathIn


def clean_dir(path: PathIn, dirs: bool = True, files: bool = True) -> str:
    """Remove empty files and directories recursively inside a directory."""
    normalized = _get_path(path)
    assert_dir(normalized)
    for basepath, dirnames, filenames in os.walk(normalized, topdown=False):
        if files:
            for filename in filenames:
                filepath = os.path.join(basepath, filename)
                if is_empty_file(filepath):
                    os.remove(filepath)
        if dirs:
            for dirname in dirnames:
                dirpath = os.path.join(basepath, dirname)
                if is_empty_dir(dirpath):
                    shutil.rmtree(dirpath)
    return normalized


def copy_dir(path: PathIn, dest: PathIn, overwrite: bool = False, **kwargs: Any) -> str:
    """Copy a directory to a destination directory path."""
    source = _get_path(path)
    target = _get_path(dest)
    assert_dir(source)
    assert_not_file(target)
    if exists(target):
        if not overwrite:
            raise FileExistsError(f"path already exists: {target}")
        remove_dir(target)
    parent = os.path.dirname(target)
    if parent:
        os.makedirs(parent, exist_ok=True)
    shutil.copytree(source, target, **kwargs)
    return target


def copy_dir_content(
    path: PathIn,
    dest: PathIn,
    overwrite: bool = False,
    **kwargs: Any,
) -> str:
    """Copy the content of a directory into another directory."""
    source = _get_path(path)
    target = _get_path(dest)
    assert_dir(source)
    assert_not_file(target)
    make_dirs(target)
    copy_function = kwargs.pop("copy_function", shutil.copy2)
    for entry in os.scandir(source):
        source_item = entry.path
        target_item = join_path(target, entry.name)
        if entry.is_dir(follow_symlinks=False):
            shutil.copytree(
                source_item,
                target_item,
                copy_function=copy_function,
                dirs_exist_ok=overwrite,
                **kwargs,
            )
        else:
            if exists(target_item) and not overwrite:
                raise FileExistsError(f"path already exists: {target_item}")
            make_dirs_for_file(target_item)
            copy_function(source_item, target_item)
    return target


def copy_file(path: PathIn, dest: PathIn, overwrite: bool = False, **kwargs: Any) -> str:
    """Copy a file to another file path or into an existing directory."""
    source = _get_path(path)
    raw_dest = os.fspath(dest)
    target = _resolve_file_destination(source, raw_dest)
    assert_file(source)
    assert_not_dir(target)
    if exists(target) and not overwrite:
        raise FileExistsError(f"path already exists: {target}")
    make_dirs_for_file(target)
    shutil.copy2(source, target, **kwargs)
    return target


def create_dir(path: PathIn, overwrite: bool = False) -> str:
    """Create a directory if needed."""
    normalized = _get_path(path)
    assert_not_file(normalized)
    if exists(normalized):
        if not overwrite:
            raise FileExistsError(f"path already exists: {normalized}")
        return normalized
    os.makedirs(normalized, exist_ok=True)
    return normalized


def make_dirs(path: PathIn) -> str:
    """Ensure a directory path exists."""
    normalized = _get_path(path)
    assert_not_file(normalized)
    os.makedirs(normalized, exist_ok=True)
    return normalized


def make_dirs_for_file(path: PathIn) -> str:
    """Ensure the parent directories for a file path exist."""
    normalized = _get_path(path)
    assert_not_dir(normalized)
    dirpath, _ = split_filepath(normalized)
    if dirpath:
        os.makedirs(dirpath, exist_ok=True)
    return dirpath or ""


def move_dir(path: PathIn, dest: PathIn, overwrite: bool = False, **kwargs: Any) -> str:
    """Move a directory to a new path."""
    source = _get_path(path)
    target = _get_path(dest)
    assert_dir(source)
    assert_not_file(target)
    if os.path.abspath(source) == os.path.abspath(target):
        return target
    if exists(target):
        if not overwrite:
            raise FileExistsError(f"path already exists: {target}")
        remove_dir(target)
    parent = os.path.dirname(target)
    if parent:
        os.makedirs(parent, exist_ok=True)
    shutil.move(source, target, **kwargs)
    return target


def move_file(path: PathIn, dest: PathIn, overwrite: bool = False, **kwargs: Any) -> str:
    """Move a file to another file path or into an existing directory."""
    source = _get_path(path)
    raw_dest = os.fspath(dest)
    target = _resolve_file_destination(source, raw_dest)
    assert_file(source)
    assert_not_dir(target)
    if os.path.abspath(source) == os.path.abspath(target):
        return target
    if exists(target):
        if not overwrite:
            raise FileExistsError(f"path already exists: {target}")
        os.remove(target)
    make_dirs_for_file(target)
    shutil.move(source, target, **kwargs)
    return target


def remove_dir(path: PathIn, **kwargs: Any) -> bool:
    """Remove a directory recursively if it exists."""
    normalized = _get_path(path)
    if not exists(normalized):
        return False
    assert_dir(normalized)
    shutil.rmtree(normalized, **kwargs)
    return not exists(normalized)


def remove_dir_content(path: PathIn) -> str:
    """Remove all direct content from a directory."""
    normalized = _get_path(path)
    assert_dir(normalized)
    for entry in os.scandir(normalized):
        if entry.is_dir(follow_symlinks=False):
            shutil.rmtree(entry.path)
        else:
            os.remove(entry.path)
    return normalized


def remove_dirs(*paths: PathIn) -> list[bool]:
    """Remove multiple directories."""
    return [remove_dir(path) for path in paths]


def remove_file(path: PathIn) -> bool:
    """Remove a file if it exists."""
    normalized = _get_path(path)
    if not exists(normalized):
        return False
    assert_file(normalized)
    os.remove(normalized)
    return not exists(normalized)


def remove_files(*paths: PathIn) -> list[bool]:
    """Remove multiple files."""
    return [remove_file(path) for path in paths]


def delete_dir(path: PathIn, **kwargs: Any) -> bool:
    """Alias for :func:`remove_dir`."""
    return remove_dir(path, **kwargs)


def delete_dir_content(path: PathIn) -> str:
    """Alias for :func:`remove_dir_content`."""
    return remove_dir_content(path)


def delete_dirs(*paths: PathIn) -> list[bool]:
    """Alias for :func:`remove_dirs`."""
    return remove_dirs(*paths)


def delete_file(path: PathIn) -> bool:
    """Alias for :func:`remove_file`."""
    return remove_file(path)


def delete_files(*paths: PathIn) -> list[bool]:
    """Alias for :func:`remove_files`."""
    return remove_files(*paths)


def rename_dir(path: PathIn, name: str) -> str:
    """Rename a directory within its current parent."""
    source = _get_path(path)
    assert_dir(source)
    parent = os.path.dirname(source)
    target = join_path(parent, name)
    assert_not_exists(target)
    os.rename(source, target)
    return target


def rename_file(path: PathIn, name: str) -> str:
    """Rename a file within its current parent directory."""
    source = _get_path(path)
    assert_file(source)
    parent, _ = split_filepath(source)
    target = join_filepath(parent, name)
    assert_not_exists(target)
    os.rename(source, target)
    return target


def rename_file_basename(path: PathIn, basename: str) -> str:
    """Rename only the basename of a file."""
    return rename_file(path, join_filename(basename, get_file_extension(path)))


def rename_file_extension(path: PathIn, extension: str) -> str:
    """Rename only the extension of a file."""
    return rename_file(path, join_filename(get_file_basename(path), extension))


def replace_dir(path: PathIn, src: PathIn, autodelete: bool = False) -> str:
    """Replace a directory at ``path`` with the directory at ``src``."""
    target = _get_path(path)
    source = _get_path(src)
    assert_not_file(target)
    assert_dir(source)
    if os.path.abspath(source) == os.path.abspath(target):
        return target
    if autodelete:
        if exists(target):
            remove_dir(target)
        parent = os.path.dirname(target)
        if parent:
            os.makedirs(parent, exist_ok=True)
        shutil.move(source, target)
        return target
    return copy_dir(source, target, overwrite=True)


def replace_file(path: PathIn, src: PathIn, autodelete: bool = False) -> str:
    """Replace a file at ``path`` with the file at ``src``."""
    target = _get_path(path)
    source = _get_path(src)
    assert_not_dir(target)
    assert_file(source)
    if os.path.abspath(source) == os.path.abspath(target):
        return target
    if autodelete:
        if exists(target):
            remove_file(target)
        make_dirs_for_file(target)
        shutil.move(source, target)
        return target
    return copy_file(source, target, overwrite=True)


def _resolve_file_destination(source: str, dest: str) -> str:
    normalized_dest = _get_path(dest)
    if (exists(normalized_dest) and is_dir(normalized_dest)) or dest.endswith(tuple(filter(None, (os.sep, os.altsep)))):
        return join_path(normalized_dest, get_filename(source))
    return normalized_dest

