from __future__ import annotations

import hashlib
import os
from datetime import datetime
from pathlib import Path
from typing import BinaryIO

from .args import get_path as _get_path
from .checks import assert_dir, assert_file
from .converters import convert_size_bytes_to_string
from .types import PathIn


def get_file_size(path: PathIn) -> int:
    """Return the size of a file in bytes."""
    normalized = _get_path(path)
    assert_file(normalized)
    return os.path.getsize(normalized)


def get_file_size_formatted(path: PathIn) -> str:
    """Return the formatted size of a file."""
    return convert_size_bytes_to_string(get_file_size(path))


def get_dir_size(path: PathIn) -> int:
    """Return the total size of all non-symlink files in a directory tree."""
    normalized = _get_path(path)
    assert_dir(normalized)
    total = 0
    for basepath, _, filenames in os.walk(normalized):
        for filename in filenames:
            filepath = os.path.join(basepath, filename)
            if not os.path.islink(filepath):
                total += os.path.getsize(filepath)
    return total


def get_dir_size_formatted(path: PathIn) -> str:
    """Return the formatted size of a directory tree."""
    return convert_size_bytes_to_string(get_dir_size(path))


def get_file_creation_date(path: PathIn) -> datetime:
    """Return a file creation datetime where supported, else ctime."""
    normalized = _get_path(path)
    assert_file(normalized)
    return datetime.fromtimestamp(_get_creation_timestamp(normalized))


def get_file_creation_date_formatted(
    path: PathIn,
    format: str = "%Y-%m-%d %H:%M:%S",
) -> str:
    """Return a formatted file creation datetime string."""
    return get_file_creation_date(path).strftime(format)


def get_file_last_modified_date(path: PathIn) -> datetime:
    """Return a file last-modified datetime."""
    normalized = _get_path(path)
    assert_file(normalized)
    return datetime.fromtimestamp(os.path.getmtime(normalized))


def get_file_last_modified_date_formatted(
    path: PathIn,
    format: str = "%Y-%m-%d %H:%M:%S",
) -> str:
    """Return a formatted file last-modified datetime string."""
    return get_file_last_modified_date(path).strftime(format)


def get_dir_creation_date(path: PathIn) -> datetime:
    """Return a directory creation datetime where supported, else ctime."""
    normalized = _get_path(path)
    assert_dir(normalized)
    return datetime.fromtimestamp(_get_creation_timestamp(normalized))


def get_dir_creation_date_formatted(
    path: PathIn,
    format: str = "%Y-%m-%d %H:%M:%S",
) -> str:
    """Return a formatted directory creation datetime string."""
    return get_dir_creation_date(path).strftime(format)


def get_dir_last_modified_date(path: PathIn) -> datetime:
    """Return the latest modification time in a directory tree."""
    normalized = _get_path(path)
    assert_dir(normalized)
    latest = os.path.getmtime(normalized)
    for basepath, dirnames, filenames in os.walk(normalized):
        for dirname in dirnames:
            latest = max(latest, os.path.getmtime(os.path.join(basepath, dirname)))
        for filename in filenames:
            latest = max(latest, os.path.getmtime(os.path.join(basepath, filename)))
    return datetime.fromtimestamp(latest)


def get_dir_last_modified_date_formatted(
    path: PathIn,
    format: str = "%Y-%m-%d %H:%M:%S",
) -> str:
    """Return a formatted directory last-modified datetime string."""
    return get_dir_last_modified_date(path).strftime(format)


def get_file_hash(path: PathIn | BinaryIO, func: str = "md5") -> str:
    """Return the hash of a file path or binary file-like object."""
    digest = hashlib.new(func)
    if isinstance(path, (str, Path, os.PathLike)):
        normalized = _get_path(path)
        assert_file(normalized)
        with open(normalized, "rb") as handle:
            _update_hash(digest, handle)
    else:
        position = path.tell() if path.seekable() else None
        if position is not None:
            path.seek(0)
        _update_hash(digest, path)
        if position is not None:
            path.seek(position)
    return digest.hexdigest()


def get_dir_hash(path: PathIn, func: str = "md5") -> str:
    """Return a deterministic hash for all files in a directory tree."""
    normalized = _get_path(path)
    assert_dir(normalized)
    digest = hashlib.new(func)
    for basepath, dirnames, filenames in os.walk(normalized):
        dirnames.sort()
        filenames.sort()
        rel_base = os.path.relpath(basepath, normalized)
        for filename in filenames:
            filepath = os.path.join(basepath, filename)
            relpath = filename if rel_base == "." else os.path.normpath(os.path.join(rel_base, filename))
            digest.update(relpath.encode("utf-8"))
            digest.update(b"\0")
            with open(filepath, "rb") as handle:
                _update_hash(digest, handle)
            digest.update(b"\0")
    return digest.hexdigest()


def _update_hash(digest: hashlib._Hash, handle: BinaryIO) -> None:
    for chunk in iter(lambda: handle.read(4096), b""):
        digest.update(chunk)


def _get_creation_timestamp(path: str) -> float:
    stats = os.stat(path)
    return getattr(stats, "st_birthtime", stats.st_ctime)

