from __future__ import annotations

import glob
import json
import os
import re
import tempfile
from collections.abc import Callable, Iterable
from datetime import date, datetime
from pathlib import Path
from typing import Any

from .args import get_path as _get_path
from .checks import assert_dir, assert_file, assert_not_dir, exists, is_dir, is_file
from .deps import require_requests
from .paths import get_filename, join_path, split_filepath
from .perms import get_permissions, set_permissions
from .types import BytesLike, PathIn


def create_file(
    path: PathIn,
    content: str | BytesLike = "",
    overwrite: bool = False,
    encoding: str = "utf-8",
    atomic: bool = False,
) -> str:
    """Create a file with optional text or binary content."""
    normalized = _get_path(path)
    assert_not_dir(normalized)
    if exists(normalized) and not overwrite:
        raise FileExistsError(f"file already exists: {normalized}")
    if isinstance(content, (bytes, bytearray, memoryview)):
        return write_file_binary(normalized, bytes(content), append=False, atomic=atomic)
    return write_file(normalized, str(content), append=False, encoding=encoding, atomic=atomic)


def read_file(path: PathIn, encoding: str = "utf-8", errors: str = "strict") -> str:
    """Read a text file."""
    normalized = _get_path(path)
    assert_file(normalized)
    with open(normalized, "r", encoding=encoding, errors=errors) as handle:
        return handle.read()


def read_file_binary(path: PathIn) -> bytes:
    """Read a binary file."""
    normalized = _get_path(path)
    assert_file(normalized)
    with open(normalized, "rb") as handle:
        return handle.read()


def read_file_from_url(url: str, encoding: str | None = None, **kwargs: Any) -> str:
    """Fetch text content from a URL using ``requests``."""
    requests = require_requests()
    response = requests.get(url, **kwargs)
    response.raise_for_status()
    try:
        if encoding is not None:
            response.encoding = encoding
        return str(response.text)
    finally:
        response.close()


def read_file_json(path: PathIn, **kwargs: Any) -> Any:
    """Read and parse a JSON file."""
    encoding = kwargs.pop("encoding", "utf-8")
    content = read_file(path, encoding=encoding)
    return json.loads(content, **kwargs)


def _normalize_line_bounds(line_start: int, line_end: int, total: int) -> tuple[int, int]:
    start = line_start if line_start >= 0 else max(0, total + line_start)
    if line_end < 0:
        end = total + line_end
    else:
        end = line_end
    return max(0, start), min(max(-1, end), total - 1)


def read_file_lines(
    path: PathIn,
    line_start: int = 0,
    line_end: int = -1,
    strip_white: bool = True,
    skip_empty: bool = True,
    encoding: str = "utf-8",
    errors: str = "strict",
) -> list[str]:
    """Read file lines, optionally slicing by inclusive line indexes."""
    normalized = _get_path(path)
    assert_file(normalized)
    if line_start == 0 and line_end == -1:
        lines = read_file(normalized, encoding=encoding, errors=errors).splitlines()
    else:
        total = read_file_lines_count(normalized)
        start, end = _normalize_line_bounds(line_start, line_end, total)
        lines = []
        with open(normalized, "r", encoding=encoding, errors=errors) as handle:
            for index, line in enumerate(handle):
                if index < start:
                    continue
                if end != -1 and index > end:
                    break
                lines.append(line.rstrip("\r\n"))
    if strip_white:
        lines = [line.strip() for line in lines]
    if skip_empty:
        lines = [line for line in lines if line]
    return lines


def read_file_lines_count(path: PathIn) -> int:
    """Count the lines in a file."""
    normalized = _get_path(path)
    assert_file(normalized)
    with open(normalized, "rb") as handle:
        return sum(1 for _ in handle)


def write_file(
    path: PathIn,
    content: str,
    append: bool = False,
    encoding: str = "utf-8",
    errors: str = "strict",
    atomic: bool = False,
) -> str:
    """Write text content to a file."""
    normalized = _get_path(path)
    assert_not_dir(normalized)
    _ensure_parent_dir(normalized)
    if atomic:
        _atomic_write_text(
            normalized,
            content,
            append=append,
            encoding=encoding,
            errors=errors,
        )
    else:
        mode = "a" if append else "w"
        with open(normalized, mode, encoding=encoding, errors=errors) as handle:
            handle.write(content)
    return normalized


def write_file_binary(
    path: PathIn,
    content: BytesLike,
    append: bool = False,
    atomic: bool = False,
) -> str:
    """Write binary content to a file."""
    normalized = _get_path(path)
    assert_not_dir(normalized)
    _ensure_parent_dir(normalized)
    payload = bytes(content)
    if atomic:
        _atomic_write_binary(normalized, payload, append=append)
    else:
        mode = "ab" if append else "wb"
        with open(normalized, mode) as handle:
            handle.write(payload)
    return normalized


def write_file_json(
    path: PathIn,
    data: Any,
    encoding: str = "utf-8",
    atomic: bool = False,
    **kwargs: Any,
) -> str:
    """Serialize JSON data to disk."""

    def default_encoder(obj: Any) -> Any:
        if isinstance(obj, (date, datetime)):
            return obj.isoformat()
        if isinstance(obj, Path):
            return str(obj)
        if isinstance(obj, set):
            return sorted(obj)
        return str(obj)

    kwargs.setdefault("default", default_encoder)
    content = json.dumps(data, **kwargs)
    return write_file(path, content, append=False, encoding=encoding, atomic=atomic)


def list_dirs(path: PathIn) -> list[str]:
    """List the direct child directories for a directory."""
    normalized = _get_path(path)
    assert_dir(normalized)
    return _filter_paths(normalized, os.listdir(normalized), predicate=is_dir)


def list_files(path: PathIn) -> list[str]:
    """List the direct child files for a directory."""
    normalized = _get_path(path)
    assert_dir(normalized)
    return _filter_paths(normalized, os.listdir(normalized), predicate=is_file)


def search_dirs(path: PathIn, pattern: str = "**/*") -> list[str]:
    """Search for directories using a glob pattern."""
    normalized = _get_path(path)
    assert_dir(normalized)
    matches = _search_paths(normalized, pattern)
    return _filter_paths(normalized, matches, predicate=is_dir)


def search_files(path: PathIn, pattern: str = "**/*.*") -> list[str]:
    """Search for files using a glob pattern."""
    normalized = _get_path(path)
    assert_dir(normalized)
    matches = _search_paths(normalized, pattern)
    return _filter_paths(normalized, matches, predicate=is_file)


def download_file(
    url: str,
    dirpath: PathIn | None = None,
    filename: str | None = None,
    chunk_size: int = 8192,
    **kwargs: Any,
) -> str:
    """Download a file from a URL and return the saved path."""
    requests = require_requests()
    response = requests.get(url, stream=True, **kwargs)
    response.raise_for_status()
    try:
        resolved_name = filename or _detect_response_filename(url, response.headers) or "archive.zip"
        target_dir = _get_path(dirpath or tempfile.gettempdir())
        os.makedirs(target_dir, exist_ok=True)
        filepath = join_path(target_dir, resolved_name)
        _ensure_parent_dir(filepath)
        with open(filepath, "wb") as handle:
            for chunk in response.iter_content(chunk_size=chunk_size):
                if chunk:
                    handle.write(chunk)
        return filepath
    finally:
        response.close()


def _atomic_write_text(
    path: str,
    content: str,
    append: bool,
    encoding: str,
    errors: str,
) -> None:
    existing_permissions = get_permissions(path) if exists(path) else None
    payload = content if not append else (read_file(path, encoding=encoding, errors=errors) + content if exists(path) else content)
    temp_fd, temp_path = tempfile.mkstemp(prefix=".fsutil-", suffix=".tmp", dir=os.path.dirname(path) or ".")
    try:
        with os.fdopen(temp_fd, "w", encoding=encoding, errors=errors) as handle:
            handle.write(payload)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temp_path, path)
        if existing_permissions is not None:
            set_permissions(path, existing_permissions)
    finally:
        if os.path.exists(temp_path):
            os.remove(temp_path)


def _atomic_write_binary(path: str, content: bytes, append: bool) -> None:
    existing_permissions = get_permissions(path) if exists(path) else None
    payload = content if not append else (read_file_binary(path) + content if exists(path) else content)
    temp_fd, temp_path = tempfile.mkstemp(prefix=".fsutil-", suffix=".tmp", dir=os.path.dirname(path) or ".")
    try:
        with os.fdopen(temp_fd, "wb") as handle:
            handle.write(payload)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temp_path, path)
        if existing_permissions is not None:
            set_permissions(path, existing_permissions)
    finally:
        if os.path.exists(temp_path):
            os.remove(temp_path)


def _detect_response_filename(url: str, headers: dict[str, str] | Any) -> str | None:
    content_disposition = headers.get("content-disposition", "") or headers.get("Content-Disposition", "")
    match = re.search(r'filename\*?=(?:UTF-8\'\')?"?([^";]+)"?', content_disposition, flags=re.IGNORECASE)
    if match:
        return os.path.basename(match.group(1).strip().strip('"'))
    filename = get_filename(url)
    return filename or None


def _ensure_parent_dir(path: str) -> None:
    dirpath, _ = split_filepath(path)
    if dirpath:
        os.makedirs(dirpath, exist_ok=True)


def _filter_paths(
    basepath: str,
    candidates: Iterable[str],
    predicate: Callable[[str], bool] | None = None,
) -> list[str]:
    paths: list[str] = []
    for candidate in candidates:
        candidate_path = candidate if os.path.isabs(candidate) else os.path.join(basepath, candidate)
        normalized = os.path.normpath(candidate_path)
        if predicate is None or predicate(normalized):
            paths.append(normalized)
    return sorted(paths)


def _search_paths(path: str, pattern: str) -> list[str]:
    return [os.path.normpath(match) for match in glob.glob(os.path.join(path, pattern), recursive=True)]
